-- 城市宠物寄养与上门喂养服务预约管理系统 数据库结构（MySQL 8）
-- 实际建表由 JPA (ddl-auto=update) 自动完成，本文件为结构说明/手动建库参考
CREATE DATABASE IF NOT EXISTS pet_db CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE pet_db;
CREATE TABLE IF NOT EXISTS sys_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, real_name VARCHAR(50), role VARCHAR(20) NOT NULL COMMENT 'ADMIN/OWNER/SITTER', phone VARCHAR(20), email VARCHAR(100), area VARCHAR(50), avatar_emoji VARCHAR(10), avatar_url VARCHAR(255) COMMENT '头像图片路径', status INT DEFAULT 1, create_time DATETIME);
CREATE TABLE IF NOT EXISTS pet (id BIGINT AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT, name VARCHAR(50), species VARCHAR(20) COMMENT '猫/狗/其他', breed VARCHAR(50), gender VARCHAR(10), age_months INT, weight DECIMAL(6,2), neutered BIT, color VARCHAR(30), personality VARCHAR(500), allergy VARCHAR(500), feeding_habit VARCHAR(500), hospital VARCHAR(100), vaccine_status VARCHAR(50), emoji VARCHAR(10), photo_url VARCHAR(255) COMMENT '宠物照片路径', create_time DATETIME);
CREATE TABLE IF NOT EXISTS service_item (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), category VARCHAR(20) COMMENT 'VISIT/WALK/BOARDING/GROOMING/ADDON', pricing_type VARCHAR(20) COMMENT 'PER_TIME/PER_DAY', price DECIMAL(10,2), duration_min INT, description VARCHAR(500), icon VARCHAR(10), cover_url VARCHAR(255) COMMENT '封面图路径', sales_count INT DEFAULT 0 COMMENT '已售数量', status INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS sitter_profile (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, area VARCHAR(50), specialties VARCHAR(500), pet_types VARCHAR(100), experience_years INT, intro VARCHAR(1000), rating DECIMAL(3,1), order_count INT, available BIT, cert_status VARCHAR(30), distance_km DECIMAL(6,2));
CREATE TABLE IF NOT EXISTS boarding_space (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), type VARCHAR(30), total_capacity INT, occupied INT DEFAULT 0, price_per_day DECIMAL(10,2), facilities VARCHAR(500), size_desc VARCHAR(100), description VARCHAR(500), status INT DEFAULT 1, photo_url VARCHAR(255) COMMENT '空间照片路径');
CREATE TABLE IF NOT EXISTS booking_order (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_no VARCHAR(30) UNIQUE, owner_id BIGINT, owner_name VARCHAR(50), pet_ids VARCHAR(200), pet_names VARCHAR(300), pet_count INT, service_id BIGINT, service_name VARCHAR(100), service_category VARCHAR(20), sitter_id BIGINT, sitter_name VARCHAR(50), space_id BIGINT, space_name VARCHAR(100), start_date DATE, end_date DATE, days INT, times_per_day INT, quantity INT, addon_names VARCHAR(500), price_detail VARCHAR(1000), base_amount DECIMAL(12,2), addon_amount DECIMAL(12,2), holiday_factor DECIMAL(4,2), holiday_amount DECIMAL(12,2), long_stay_discount DECIMAL(12,2), multi_pet_discount DECIMAL(12,2), coupon_discount DECIMAL(12,2), total_amount DECIMAL(12,2), user_coupon_id BIGINT, status VARCHAR(20) COMMENT 'PENDING/CONFIRMED/ACCEPTED/IN_SERVICE/COMPLETED/CANCELLED/REFUNDED', pay_status VARCHAR(20), area VARCHAR(50), address VARCHAR(500), remark VARCHAR(500), create_time DATETIME, update_time DATETIME);
CREATE TABLE IF NOT EXISTS checkin_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT, order_no VARCHAR(30), space_id BIGINT, space_name VARCHAR(100), pet_names VARCHAR(300), checkin_time DATETIME, checkout_time DATETIME, status VARCHAR(10) COMMENT 'IN/OUT', operator VARCHAR(50), remark VARCHAR(500));
CREATE TABLE IF NOT EXISTS service_report (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT, order_no VARCHAR(30), sitter_id BIGINT, sitter_name VARCHAR(50), report_date DATE, fed BIT, water_changed BIT, litter_cleaned BIT, played BIT, bathed BIT, walked BIT, appetite VARCHAR(30), spirit VARCHAR(30), excretion VARCHAR(30), temperature DECIMAL(4,1), photo_url VARCHAR(2000) COMMENT '服务照片路径(逗号分隔多张)', content VARCHAR(1000), create_time DATETIME);
CREATE TABLE IF NOT EXISTS walk_track (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT, order_no VARCHAR(30), sitter_id BIGINT, pet_name VARCHAR(100), points VARCHAR(4000) COMMENT 'JSON轨迹点[{lng,lat,t}]', distance_km DECIMAL(8,2), duration_min INT, pace_min_per_km DECIMAL(6,1), walk_date DATE, create_time DATETIME);
CREATE TABLE IF NOT EXISTS health_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, pet_id BIGINT, pet_name VARCHAR(50), type VARCHAR(20) COMMENT '疫苗/驱虫/体检/体重', name VARCHAR(100), record_date DATE, next_due_date DATE, weight DECIMAL(6,2), note VARCHAR(500), create_time DATETIME);
CREATE TABLE IF NOT EXISTS review (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT, order_no VARCHAR(30), owner_id BIGINT, owner_name VARCHAR(50), sitter_id BIGINT, sitter_name VARCHAR(50), rating INT, content VARCHAR(1000), tags VARCHAR(200), hidden BIT, create_time DATETIME);
CREATE TABLE IF NOT EXISTS coupon (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), type VARCHAR(20) COMMENT 'FULL_REDUCE/DISCOUNT', threshold DECIMAL(10,2), off_amount DECIMAL(10,2), discount_rate DECIMAL(4,2), total_count INT, claimed_count INT, valid_from DATE, valid_to DATE, status INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS user_coupon (id BIGINT AUTO_INCREMENT PRIMARY KEY, coupon_id BIGINT, user_id BIGINT, status VARCHAR(20) COMMENT 'UNUSED/USED/EXPIRED', order_id BIGINT, claim_time DATETIME, use_time DATETIME);
CREATE TABLE IF NOT EXISTS payment (id BIGINT AUTO_INCREMENT PRIMARY KEY, txn_no VARCHAR(40) UNIQUE, order_id BIGINT, order_no VARCHAR(30), user_id BIGINT, user_name VARCHAR(50), amount DECIMAL(12,2), method VARCHAR(30), type VARCHAR(10) COMMENT 'PAY/REFUND', status VARCHAR(20), create_time DATETIME);
CREATE TABLE IF NOT EXISTS notice (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200), content VARCHAR(2000), type VARCHAR(30), publisher VARCHAR(50), create_time DATETIME);
CREATE TABLE IF NOT EXISTS message (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, title VARCHAR(200), content VARCHAR(1000), type VARCHAR(20), read_flag BIT, create_time DATETIME);
